/* Kelas VII — Semester 2 — Asmaul Husna: al-Karim, al-Mumin, al-Wakil, al-Matin — 50 soal */
window.BSRegister({
'id':'k7-asmaul-husna-2','grade':7,'semester':2,'order':11,
'title':'Asmaul Husna: al-Karim, al-Mumin, al-Wakil, al-Matin',
'desc':'Makna dan dalil Asmaul Husna al-Karim, al-Mumin, al-Wakil, dan al-Matin, pengaruh penghayatan keempatnya terhadap perilaku, serta contoh penerapannya dalam kehidupan sehari-hari.',
'kd':'Menganalisis Asmaul Husna (al-Karim, al-Mumin, al-Wakil, al-Matin) beserta dalilnya, dan menampilkan perilaku yang mencerminkan penghayatan terhadap Asmaul Husna tersebut.',
'questions':[{level:'HOTS',indicator:'Menentukan dalil naqli tentang Asmaul Husna',text:'Ayat yang menyebut bahwa bagi Allah nama-nama yang baik dan memerintahkan berdoa dengan menyebut nama-nama itu adalah ...',options:['Q.S. Thaha [20]: 8','Q.S. al-Ikhlas [112]: 1','Q.S. al-Hasyr [59]: 24','Q.S. al-Araf [7]: 180'],answer:3,explanation:'Q.S. al-Araf [7]: 180 berbunyi dan bagi Allah nama-nama yang baik maka bermohonlah kepada-Nya dengan menyebut nama-nama itu, dan tinggalkanlah orang-orang yang menyimpang dari kebenaran dalam menyebut nama-nama-Nya, kelak mereka akan mendapat balasan terhadap apa yang telah mereka kerjakan. Ayat ini merupakan dasar penetapan asmaul husna sekaligus dasar adab berdoa yaitu memilih nama yang sesuai dengan isi permohonan. Hadis riwayat al-Bukhari dan Muslim menyebut bahwa Allah memiliki sembilan puluh sembilan nama dan barangsiapa menghafalnya akan masuk surga. Adapun Q.S. al-Hasyr [59]: 24 menyebut beberapa nama Allah sebagai penutup surah, Q.S. al-Ikhlas [112]: 1 berisi penegasan keesaan Allah, dan Q.S. Thaha [20]: 8 menegaskan bahwa tidak ada tuhan selain Allah yang memiliki nama-nama yang baik.'},
{level:'HOTS',indicator:'Menganalisis makna al-Karim',text:'Al-Karim merupakan salah satu nama Allah. Analisis yang paling tepat terhadap makna al-Karim adalah ...',options:['al-Karim berarti Allah Maha Keras sehingga seluruh makhluk takut kepada-Nya','al-Karim berarti Allah memberi balasan sesuai jumlah amal manusia tanpa kelebihan','al-Karim berarti Allah hanya memberi kepada orang yang berdoa kepada-Nya','Maha Pemurah yang memberi tanpa diminta dan Maha Pemaaf'],answer:3,explanation:'Para ulama menjelaskan bahwa al-Karim berasal dari akar kata yang mencakup makna kemuliaan dan kemurahan. Q.S. al-Infitar [82]: 6 menyebut pertanyaan kepada manusia tentang apa yang memperdayakan mereka terhadap Tuhan Yang Maha Pemurah atau al-Karim, yang dalam konteks ayat itu menunjukkan kemurahan Allah yang seharusnya mencegah manusia bermaksiat. Q.S. an-Naml [27]: 40 menyebut bahwa barangsiapa bersyukur maka sesungguhnya ia bersyukur untuk dirinya sendiri dan barangsiapa kufur maka sesungguhnya Tuhanku Maha Kaya lagi Maha Mulia. Q.S. ar-Rahman [55]: 27 menyebut bahwa wajah Tuhan yang memiliki kebesaran dan kemuliaan tetap kekal. Hadis juga menyebut bahwa Allah Maha Pemurah dan menyukai orang yang pemurah. Karena itu al-Karim mencakup kemurahan, kemuliaan, dan keluasan ampunan.'},
{level:'HOTS',indicator:'Menentukan perilaku yang mencerminkan al-Karim',text:'Perilaku yang paling mencerminkan penghayatan terhadap nama al-Karim adalah ...',options:['memberi tanpa diminta, tanpa pamrih, dan memaafkan yang meminta maaf','memberi bantuan kepada orang lain dengan menyebut-nyebut pemberiannya','memberi dengan jumlah yang besar sekali saja agar dianggap dermawan','memberi hanya kepada orang yang diperkirakan akan membalas kebaikannya'],answer:0,explanation:'Q.S. al-Lail [92]: 18-20 menggambarkan orang yang menafkahkan hartanya untuk menyucikan diri dan tidak ada seorang pun memberikan nikmat kepadanya yang harus dibalasnya, melainkan semata-mata mengharapkan wajah Tuhannya Yang Mahatinggi. Q.S. al-Insan [76]: 9 menggambarkan ucapan orang saleh bahwa kami memberi makanan kepada kalian semata-mata mengharapkan wajah Allah dan tidak menghendaki balasan maupun ucapan terima kasih dari kalian. Q.S. al-Baqarah [2]: 264 melarang menghilangkan pahala sedekah dengan menyebut-nyebutnya dan menyakiti perasaan penerima. Hadis menyebut bahwa Allah Maha Pemurah dan menyukai orang yang pemurah. Hadis juga menyebut bahwa tidak ada yang memaafkan melainkan Allah menambah kemuliaannya dan bahwa barangsiapa menutupi aib seorang muslim maka Allah menutupi aibnya di dunia dan akhirat. Karena itu kemurahan yang meneladani al-Karim adalah yang tanpa pamrih, tanpa menyebut-nyebut, dan tetap berlangsung walaupun pernah diperlakukan tidak baik.'},
{level:'HOTS',indicator:'Menganalisis makna al-Mumin',text:'Al-Mumin merupakan salah satu nama Allah. Analisis yang paling tepat terhadap makna al-Mumin adalah ...',options:['al-Mumin berarti Allah Maha Menakuti sehingga makhluk selalu dalam kecemasan','al-Mumin berarti Allah membenarkan seluruh ucapan manusia yang mengaku beriman','Allah membenarkan rasul-Nya dengan mukjizat dan memberi rasa aman','al-Mumin berarti Allah memberi keamanan kepada seluruh makhluk tanpa syarat'],answer:2,explanation:'Q.S. al-Hasyr [59]: 23 menyebut al-Mumin sebagai salah satu nama Allah dalam rangkaian al-Malik al-Quddus as-Salam al-Mumin al-Muhaimin al-Aziz al-Jabbar al-Mutakabbir. Q.S. al-Anam [6]: 82 menyebut bahwa orang-orang yang beriman dan tidak mencampur iman mereka dengan kezaliman, mereka itulah yang memperoleh keamanan dan mereka itu orang-orang yang mendapat petunjuk. Q.S. Quraisy [106]: 3-4 menyebut nikmat rasa aman dari ketakutan sebagai karunia Allah. Para ulama menjelaskan bahwa al-Mumin juga berarti Allah membenarkan rasul-rasul-Nya dengan menurunkan mukjizat, dan berarti bahwa janji Allah benar sehingga tidak mungkin ingkar sebagaimana Q.S. ar-Rum [30]: 6 menyebut bahwa janji Allah tidak dapat diingkari. Hadis juga menyebut bahwa seorang mukmin adalah orang yang manusia lain merasa aman terhadap hartanya dan jiwanya dari gangguannya.'},
{level:'HOTS',indicator:'Menentukan perilaku yang mencerminkan al-Mumin',text:'Perilaku yang paling mencerminkan penghayatan terhadap nama al-Mumin adalah ...',options:['menyerahkan seluruh urusan keamanan kepada pihak berwenang tanpa ikut menjaga lingkungan','memberi rasa aman dengan cara menyembunyikan kejahatan orang lain sehingga pelaku tidak dihukum','memberi rasa aman hanya kepada orang yang dikenal dan disukai','menjadi sumber rasa aman dengan jujur dan menepati janji'],answer:3,explanation:'Hadis menyebut bahwa seorang muslim adalah orang yang kaum muslimin selamat dari gangguan lisan dan tangannya, dan seorang mukmin adalah orang yang manusia lain merasa aman terhadap harta dan jiwanya dari gangguannya. Q.S. al-Anam [6]: 82 menyebut bahwa keamanan diperoleh oleh orang yang beriman dan tidak mencampur imannya dengan kezaliman. Hadis menyebut bahwa tidak beriman seseorang yang tidur kenyang sedangkan tetangganya kelaparan di sampingnya. Hadis juga menganjurkan menolong orang yang dizalimi dan yang menzalimi dengan mencegahnya dari kezaliman. Q.S. al-Maidah [5]: 2 memerintahkan tolong-menolong dalam kebaikan dan melarang tolong-menolong dalam dosa. Adapun menyembunyikan kejahatan sehingga pelaku tidak memperoleh pembinaan bukan memberi rasa aman melainkan membiarkan kezaliman berlanjut, karena memberi rasa aman tidak berarti melindungi pelaku dari tanggung jawab atas perbuatannya.'},
{level:'HOTS',indicator:'Menganalisis makna al-Wakil',text:'Al-Wakil merupakan salah satu nama Allah. Analisis yang paling tepat terhadap makna al-Wakil adalah ...',options:['al-Wakil berarti Allah mewakilkan seluruh urusan kepada malaikat sehingga Allah tidak terlibat','al-Wakil berarti manusia tidak perlu berusaha karena Allah telah mengurus segala sesuatu','Allah Maha Pemelihara dan Mencukupi bagi yang bersandar setelah berusaha','al-Wakil berarti Allah menyerahkan urusan hamba kepada hamba itu sendiri tanpa pertolongan'],answer:2,explanation:'Q.S. Ali Imran [3]: 173 mencatat ucapan orang beriman bahwa cukuplah Allah menjadi penolong kami dan Allah merupakan sebaik-baik pelindung, yang dalam riwayat lain diucapkan dengan menyebut Allah sebagai wakil. Q.S. al-Anfal [8]: 2-4 menyebut ciri orang beriman yaitu yang ketika disebut nama Allah bergetar hatinya, ketika dibacakan ayat-ayat-Nya bertambah imannya, dan kepada Tuhan mereka bertawakal. Q.S. ath-Thalaq [65]: 3 menyebut bahwa barangsiapa bertawakal kepada Allah maka Dia akan mencukupkannya. Q.S. al-Anam [6]: 102 menyebut bahwa demikianlah Allah Tuhanmu, tidak ada tuhan selain Dia, pencipta segala sesuatu, maka sembahlah Dia dan Dia adalah pemelihara segala sesuatu. Hadis juga memerintahkan mengikat kendaraan terlebih dahulu kemudian bertawakal, yang menunjukkan bahwa menyerahkan urusan kepada Allah tidak berarti meninggalkan usaha.'},
{level:'HOTS',indicator:'Menentukan perilaku yang mencerminkan al-Wakil',text:'Perilaku yang paling mencerminkan penghayatan terhadap nama al-Wakil adalah ...',options:['berusaha lalu menggantungkan seluruh harapan pada kemampuannya sendiri karena kemampuan merupakan penentu hasil','tidak berusaha sama sekali karena yakin Allah akan mencukupi','berusaha sekuat tenaga lalu menyerahkan hasilnya kepada Allah','berusaha setengah hati karena hasil sudah ditentukan Allah'],answer:2,explanation:'Q.S. Ali Imran [3]: 159 memerintahkan bermusyawarah dalam urusan kemudian apabila telah membulatkan tekad maka bertawakallah kepada Allah, yang menunjukkan bahwa tawakal dilakukan setelah usaha. Hadis memerintahkan mengikat kendaraan terlebih dahulu kemudian bertawakal. Q.S. ath-Thalaq [65]: 3 menyebut bahwa barangsiapa bertawakal kepada Allah maka Dia akan mencukupkannya. Q.S. al-Baqarah [2]: 216 menyebut bahwa boleh jadi manusia membenci sesuatu padahal sesuatu itu baik bagi mereka, sehingga hasil yang tidak sesuai harapan tetap mengandung kebaikan. Hadis melarang ucapan seandainya ketika menghadapi kegagalan karena membuka perbuatan setan. Hadis juga menyebut bahwa barangsiapa mencari ridha Allah walaupun manusia marah maka Allah mencukupkannya. Karena itu menyerahkan urusan kepada Allah setelah berusaha merupakan wujud penghayatan al-Wakil, sedangkan tidak berusaha merupakan kesalahpahaman dan menggantungkan hati pada kemampuan sendiri merupakan bentuk ketergantungan pada makhluk.'},
{level:'HOTS',indicator:'Menganalisis makna al-Matin',text:'Al-Matin merupakan salah satu nama Allah. Analisis yang paling tepat terhadap makna al-Matin adalah ...',options:['al-Matin berarti Allah Maha Keras dalam memberi hukuman','al-Matin berarti Allah Maha Kuat secara fisik sehingga dapat mengalahkan makhluk','al-Matin berarti Allah tidak dapat dikalahkan tetapi dapat dipengaruhi oleh doa manusia','kekuatan Allah sempurna, tidak berkurang, dan tidak dapat dikalahkan'],answer:3,explanation:'Q.S. adz-Dzariyat [51]: 58 berbunyi sesungguhnya Allah Dialah Maha Pemberi rezeki yang mempunyai kekuatan lagi sangat kokoh. Q.S. al-Anfal [8]: 52 menyebut kekuatan Allah yang tidak dapat dikalahkan sebagaimana keadaan pengikut Fir aun. Hadis qudsi menyebut bahwa kebesaran merupakan selendang Allah dan keperkasaan merupakan pakaian-Nya sehingga barangsiapa menyaingi-Nya dalam salah satu dari keduanya akan dimasukkan ke neraka, yang menunjukkan bahwa kekuatan dan keperkasaan merupakan sifat Allah yang tidak dapat disaingi. Q.S. al-Hajj [22]: 74 menyebut bahwa Allah Maha Kuat lagi Maha Perkasa. Hadis juga menyebut bahwa mukmin yang kuat lebih baik dan lebih dicintai Allah daripada mukmin yang lemah, dan dalam setiap keadaan terdapat kebaikan. Adapun doa manusia tidak memengaruhi kekuatan Allah melainkan merupakan sebab yang telah ditetapkan Allah untuk memperoleh kebaikan, dan Allah mengabulkan doa sesuai kehendak dan hikmah-Nya.'},
{level:'HOTS',indicator:'Menentukan perilaku yang mencerminkan al-Matin',text:'Perilaku yang paling mencerminkan penghayatan terhadap nama al-Matin adalah ...',options:['bertahan pada pendapat sendiri walaupun telah terbukti keliru karena menunjukkan keteguhan','mengandalkan kekuatan fisik sendiri ketika menghadapi persoalan','menyerah ketika menghadapi tekanan karena tekanan pasti lebih kuat daripada prinsip','teguh pada kebenaran, bersandar kepada Allah, dan tetap menerima nasihat'],answer:3,explanation:'Q.S. al-Ahzab [33]: 23 memuji orang mukmin yang menepati apa yang mereka janjikan kepada Allah, dan di antara mereka ada yang gugur serta ada yang menunggu-nunggu, dan mereka tidak mengubah janjinya, yang menggambarkan keteguhan dalam memegang kebenaran. Q.S. Ali Imran [3]: 8 berisi doa agar Allah tidak memalingkan hati setelah diberi petunjuk, yang menunjukkan bahwa keteguhan merupakan karunia yang harus dimohon. Hadis menyebut bahwa mukmin yang kuat lebih baik dan lebih dicintai Allah daripada mukmin yang lemah. Hadis juga menyebut bahwa apabila seseorang diberi nasihat maka hendaklah menerimanya, dan bahwa sombong adalah menolak kebenaran, sehingga menolak nasihat yang benar bukan keteguhan melainkan kesombongan. Hadis menyebut bahwa jihad yang paling utama adalah menyampaikan kata yang benar di hadapan penguasa yang zalim, yang merupakan puncak keteguhan dalam kebenaran.'},
{level:'HOTS',indicator:'Menganalisis hubungan keempat nama dalam satu rangkaian perilaku',text:'Keempat nama al-Karim, al-Mumin, al-Wakil, dan al-Matin dipelajari dalam satu materi. Analisis yang paling tepat terhadap keterkaitan keempatnya dalam membentuk perilaku seorang muslim adalah ...',options:['keempatnya hanya berkaitan dalam bentuk doa bukan dalam perilaku','keempat nama tersebut tidak berkaitan karena memiliki makna yang berbeda','keterkaitan keempatnya berarti seorang muslim harus memilih salah satu untuk dihayati','keempatnya membentuk karakter dermawan, terpercaya, tenang, dan teguh'],answer:3,explanation:'Q.S. al-Hasyr [59]: 23 menyebut rangkaian nama Allah yang saling melengkapi untuk menggambarkan kesempurnaan-Nya. Hadis menyebut bahwa Allah memiliki sembilan puluh sembilan nama dan barangsiapa menghafalnya akan masuk surga, dan para ulama menjelaskan bahwa menghafal mencakup menghafal lafaznya, memahami maknanya, serta beramal sesuai tuntutannya. Hadis juga menyebut bahwa Allah Maha Pemurah dan menyukai orang yang pemurah, serta menyebut bahwa seorang mukmin adalah orang yang manusia lain merasa aman dari gangguannya. Q.S. ath-Thalaq [65]: 3 menyebut kecukupan bagi orang yang bertawakal. Q.S. al-Ahzab [33]: 23 memuji keteguhan orang mukmin. Karena itu keempat nama tersebut membentuk satu kesatuan karakter yang menjadikan seorang muslim dermawan dan pemaaf, dapat dipercaya dan memberi rasa aman, tenang dalam menerima hasil, serta teguh dalam memegang kebenaran.'},
{level:'HOTS',indicator:'Menentukan contoh kemurahan Allah yang tidak terputus walaupun manusia bermaksiat',text:'Contoh yang paling tepat sebagai bukti kemurahan Allah yang tidak terputus walaupun manusia bermaksiat adalah ...',options:['Allah segera menghukum setiap pelaku maksiat agar jera','Allah tetap memberi rezeki dan kesempatan bertaubat tanpa segera menghukum','Allah memberi nikmat hanya kepada orang yang beribadah secara terus-menerus','Allah mengurangi nikmat kepada pelaku maksiat sehingga hidupnya selalu sulit'],answer:1,explanation:'Q.S. Fathir [35]: 45 berbunyi dan kalau sekiranya Allah menyiksa manusia disebabkan usahanya niscaya Dia tidak akan meninggalkan di atas permukaan bumi suatu makhluk yang melata pun, akan tetapi Allah menangguhkan mereka sampai waktu yang tertentu, sehingga apabila datang ajal mereka maka sesungguhnya Allah Maha Melihat hamba-hamba-Nya. Q.S. az-Zumar [39]: 53 melarang berputus asa dari rahmat Allah dan menyebut bahwa Allah mengampuni seluruh dosa bagi yang kembali kepada-Nya. Q.S. Ibrahim [14]: 34 menyebut bahwa Allah telah memberikan kepada manusia segala apa yang dimintanya dan apabila menghitung nikmat Allah niscaya tidak mampu menghitungnya. Hadis qudsi menyebut bahwa rahmat Allah mendahului kemurkaan-Nya. Hadis juga menyebut bahwa Allah membentangkan tangan-Nya pada malam hari untuk menerima taubat orang yang berbuat dosa pada siang hari dan membentangkan tangan-Nya pada siang hari untuk menerima taubat orang yang berbuat dosa pada malam hari.'},
{level:'HOTS',indicator:'Menganalisis hikmah diberi rasa aman sebagai nikmat',text:'Q.S. Quraisy [106]: 3-4 menyebut nikmat rasa aman dari ketakutan dan nikmat rezeki. Analisis yang paling tepat terhadap hikmah disebutkannya rasa aman sebagai nikmat besar adalah ...',options:['rasa aman menjadi syarat beribadah, mencari rezeki, dan menuntut ilmu','rasa aman tidak berhubungan dengan rezeki karena keduanya nikmat yang terpisah','rasa aman disebut karena merupakan nikmat yang paling mudah diperoleh','rasa aman disebut hanya bagi penduduk Mekah pada masa Rasulullah'],answer:0,explanation:'Q.S. Quraisy [106]: 3-4 berbunyi maka hendaklah mereka menyembah Tuhan pemilik rumah ini yaitu Baitullah, yang telah memberi makanan kepada mereka untuk menghilangkan lapar dan mengamankan mereka dari ketakutan. Q.S. al-Ankabut [29]: 67 menyebut bahwa penduduk Mekah mengetahui bahwa Allah menjadikan tanah haram mereka aman sedangkan manusia di sekitarnya diculik. Q.S. al-Baqarah [2]: 126 mencatat doa Nabi Ibrahim agar negeri dijadikan aman dan penduduknya diberi rezeki. Hadis menyebut bahwa barangsiapa bangun di pagi hari dalam keadaan aman di tempat tinggalnya, sehat badannya, dan memiliki makanan untuk hari itu maka seolah-olah dunia telah dikumpulkan baginya. Karena itu rasa aman merupakan syarat bagi seluruh kegiatan hidup dan merupakan nikmat yang harus disyukuri dengan beribadah dan menjaga keamanan bersama.'},
{level:'HOTS',indicator:'Menentukan contoh menyerahkan urusan kepada Allah dalam kehidupan pelajar',text:'Contoh yang paling tepat sebagai wujud menyerahkan urusan kepada Allah melalui penghayatan al-Wakil bagi seorang pelajar adalah ...',options:['tidak belajar karena hasil ujian telah ditentukan Allah','belajar dengan mengandalkan kecerdasan sendiri karena kecerdasan merupakan penentu hasil','belajar sepanjang malam tanpa istirahat agar memperoleh hasil terbaik','belajar sungguh-sungguh, berdoa, lalu menerima hasil dengan lapang dada'],answer:3,explanation:'Q.S. Ali Imran [3]: 159 memerintahkan bermusyawarah kemudian bertawakal setelah membulatkan tekad, yang menunjukkan urutan usaha terlebih dahulu kemudian penyerahan. Hadis memerintahkan mengikat kendaraan terlebih dahulu kemudian bertawakal. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga belajar sesuai jadwal lebih baik daripada memaksakan diri sepanjang malam. Hadis menyebut bahwa tubuh memiliki hak atas dirinya. Q.S. al-Baqarah [2]: 286 menegaskan bahwa Allah tidak membebani seseorang melainkan sesuai kesanggupannya. Hadis melarang ucapan seandainya ketika menghadapi kegagalan karena membuka perbuatan setan. Q.S. al-Baqarah [2]: 216 menyebut bahwa boleh jadi manusia membenci sesuatu padahal sesuatu itu baik bagi mereka. Karena itu belajar sungguh-sungguh, berdoa, tenang ketika ujian, dan menerima hasil dengan lapang dada merupakan wujud menyerahkan urusan kepada Allah.'},
{level:'HOTS',indicator:'Menganalisis bahaya merasa cukup tanpa Allah',text:'Q.S. al-Ankabut [29]: 6 menyebut bahwa siapa yang berjihad atau bersungguh-sungguh maka sesungguhnya kesungguhannya itu untuk dirinya sendiri, dan sesungguhnya Allah benar-benar Maha Kaya dari seluruh alam. Analisis yang paling tepat terhadap kandungan ayat tersebut adalah ...',options:['ayat itu berarti usaha manusia tidak bermanfaat bagi Allah sehingga usaha manusia tidak berguna','ayat itu berarti Allah tidak memperhatikan usaha manusia','manfaat ketaatan kembali kepada manusia sedangkan Allah tidak memerlukannya','ayat itu hanya berlaku bagi orang yang berjihad dalam peperangan'],answer:2,explanation:'Q.S. al-Ankabut [29]: 6 berbunyi dan barangsiapa berjihad maka sesungguhnya jihadnya itu untuk dirinya sendiri, sesungguhnya Allah benar-benar Maha Kaya dari seluruh alam. Q.S. Luqman [31]: 12 menyebut bahwa barangsiapa bersyukur maka sesungguhnya ia bersyukur untuk dirinya sendiri dan barangsiapa kufur maka sesungguhnya Allah Maha Kaya lagi Maha Terpuji. Q.S. Muhammad [47]: 38 menyebut bahwa barangsiapa bakhil maka sesungguhnya ia bakhil terhadap dirinya sendiri dan Allah Maha Kaya sedangkan manusia miskin. Hadis qudsi menyebut bahwa ketaatan seluruh makhluk tidak menambah kerajaan Allah dan kemaksiatan mereka tidak menguranginya. Q.S. ath-Thalaq [65]: 3 menyebut bahwa barangsiapa bertawakal kepada Allah maka Dia akan mencukupkannya. Karena itu manfaat ketaatan dan penyerahan urusan kepada Allah kembali kepada manusia, sedangkan merasa cukup tanpa Allah merupakan kerugian karena menghilangkan sumber kecukupan yang sejati.'},
{level:'HOTS',indicator:'Menentukan perilaku kemurahan dalam menghadapi orang yang pernah menyakiti',text:'Seseorang pernah disakiti oleh temannya lalu teman itu meminta maaf dan memerlukan bantuan. Perilaku yang paling mencerminkan al-Karim adalah ...',options:['memaafkan tulus tanpa mengungkit dan tetap membantunya','membantu dengan menyebut kesalahan masa lalunya agar ia tidak mengulangi','menolak membantu karena permintaan maaf tidak menghapus luka yang pernah ditimbulkan','membantu dengan jumlah yang lebih kecil karena pernah disakiti'],answer:0,explanation:'Q.S. Ali Imran [3]: 134 menyebut ciri orang bertakwa yaitu yang menafkahkan harta dalam keadaan lapang maupun sempit, menahan amarah, dan memaafkan kesalahan orang lain, dan Allah mencintai orang yang berbuat kebaikan. Q.S. an-Nur [24]: 22 menganjurkan memaafkan dan berlapang dada serta mengingatkan agar menyukai bahwa Allah mengampuni. Hadis menyebut bahwa tidak ada yang memaafkan melainkan Allah menambah kemuliaannya. Hadis juga menyebut bahwa barangsiapa menutupi aib seorang muslim maka Allah menutupi aibnya di dunia dan akhirat, sehingga menceritakan kesalahan yang telah dimaafkan merupakan pelanggaran terhadap penjagaan aib. Q.S. al-Baqarah [2]: 264 melarang menghilangkan pahala pemberian dengan menyebut-nyebutnya dan menyakiti perasaan penerima. Karena itu memaafkan dengan tulus, membantu secara wajar tanpa mengungkit, dan menjaga aib merupakan wujud kemurahan yang meneladani al-Karim.'},
{level:'HOTS',indicator:'Menganalisis kedudukan rasa aman dalam iman',text:'Q.S. al-Anam [6]: 82 menyebut bahwa orang yang beriman dan tidak mencampur imannya dengan kezaliman akan memperoleh keamanan dan petunjuk. Analisis yang paling tepat terhadap hubungan iman dengan rasa aman adalah ...',options:['rasa aman merupakan buah dari iman yang bersih dari kezaliman','rasa aman tidak berhubungan dengan iman karena rasa aman merupakan persoalan keamanan lingkungan','rasa aman diperoleh hanya oleh orang yang tidak pernah berbuat salah','rasa aman hanya diperoleh di akhirat sehingga tidak dirasakan di dunia'],answer:0,explanation:'Q.S. al-Anam [6]: 82 berbunyi orang-orang yang beriman dan tidak mencampur iman mereka dengan kezaliman, mereka itulah yang memperoleh keamanan dan mereka itu orang-orang yang mendapat petunjuk. Hadis menjelaskan bahwa kezaliman yang dimaksud dalam ayat itu adalah syirik dengan merujuk pada Q.S. Luqman [31]: 13, tetapi para ulama menjelaskan bahwa ayat itu mencakup seluruh bentuk kezaliman dengan tingkat yang berbeda. Q.S. ar-Rad [28]: 28 menegaskan bahwa hati menjadi tenteram dengan mengingat Allah. Hadis menyebut bahwa seorang mukmin adalah orang yang manusia lain merasa aman terhadap harta dan jiwanya dari gangguannya. Hadis juga menyebut bahwa dosa merupakan keraguan dalam jiwa sedangkan kebaikan merupakan ketenangan. Karena itu iman yang bersih dari kezaliman menghasilkan rasa aman di dunia berupa ketenangan batin dan perlindungan Allah, serta rasa aman di akhirat berupa keselamatan dari azab.'},
{level:'HOTS',indicator:'Menentukan perilaku keteguhan ketika ditawari sesuatu yang melanggar ketentuan',text:'Seorang pelajar ditawari oleh temannya untuk ikut dalam perbuatan yang melanggar ketentuan agama dengan imbalan uang. Perilaku yang paling mencerminkan al-Matin adalah ...',options:['menolak tetapi tetap berada di tempat itu agar tidak dianggap sombong','menerima tawaran itu sekali saja karena tidak akan diketahui orang','menolak tegas tanpa kasar lalu segera meninggalkan tempat itu','menerima tawaran itu lalu menyedekahkan uangnya agar menjadi halal'],answer:2,explanation:'Q.S. Yusuf [12]: 23-24 menggambarkan Yusuf yang menolak godaan dengan berlindung kepada Allah dan segera meninggalkan tempat itu, yang menjadi teladan menolak godaan dengan tegas dan segera menjauh. Q.S. Yusuf [12]: 33 mencatat doa Yusuf bahwa penjara lebih ia sukai daripada memenuhi ajakan mereka, yang menunjukkan keteguhan memilih penderitaan daripada maksiat. Hadis menyebut bahwa salah satu golongan yang dinaungi Allah adalah laki-laki yang diajak oleh perempuan berkedudukan lalu berkata aku takut kepada Allah. Hadis juga menyebut bahwa tidaklah kelembutan ada pada sesuatu melainkan ia menghiasinya, sehingga penolakan dilakukan dengan tegas tetapi tidak kasar. Hadis melarang berdusta dan menyebut bahwa menerima uang haram tidak menjadi halal dengan disedekahkan, sebab hadis menyebut bahwa setiap daging yang tumbuh dari yang haram maka neraka lebih pantas baginya. Hadis juga menganjurkan mendoakan kebaikan bagi orang yang berbuat salah.'},
{level:'HOTS',indicator:'Menganalisis hikmah diperintahkannya berdoa dengan asmaul husna',text:'Allah memerintahkan berdoa dengan menyebut asmaul husna. Analisis yang paling tepat terhadap hikmah perintah tersebut adalah ...',options:['doa disertai pengenalan kepada Allah melalui nama yang sesuai permohonan','perintah itu berarti doa tanpa menyebut nama Allah tidak diterima','perintah itu agar doa menjadi lebih panjang dan berkesan','perintah itu hanya berlaku bagi doa yang dipanjatkan setelah salat'],answer:0,explanation:'Q.S. al-Araf [7]: 180 memerintahkan bermohon kepada Allah dengan menyebut nama-nama-Nya yang baik. Hadis menyebut bahwa Allah memiliki sembilan puluh sembilan nama dan barangsiapa menghafalnya akan masuk surga, dan para ulama menjelaskan bahwa menghafal mencakup menghafal lafaznya, memahami maknanya, dan beramal sesuai tuntutannya. Q.S. al-Baqarah [2]: 186 menyebut bahwa Allah mengabulkan doa orang yang memohon kepada-Nya. Hadis juga menyebut bahwa doa merupakan ibadah, sehingga doa bukan sekadar permintaan melainkan bentuk penghambaan. Q.S. al-Fatihah [1]: 1-4 dibuka dengan menyebut ar-Rahman, ar-Rahim, dan Malik yaumiddin sebelum sampai pada permohonan petunjuk, yang menunjukkan bahwa menyebut nama Allah mendahului permintaan. Karena itu hikmah perintah tersebut adalah pengenalan terhadap Allah yang menghasilkan keyakinan dan kedekatan, dan doa tetap diterima tanpa menyebut nama tertentu selama memenuhi adabnya.'},
{level:'HOTS',indicator:'Menentukan cara berdoa sesuai nama al-Karim',text:'Seorang pelajar akan berdoa memohon kelapangan rezeki bagi keluarganya dan ampunan atas kesalahannya. Cara berdoa yang paling tepat sesuai nama al-Karim adalah ...',options:['berdoa tanpa menyebut nama Allah karena Allah telah mengetahui isi doa','menyebut al-Karim untuk memohon rezeki dan ampunan disertai usaha halal','menyebut seluruh asmaul husna sekaligus agar doa lebih mungkin dikabulkan','menyebut nama al-Karim berulang kali tanpa memahami maknanya agar terasa lebih khusyuk'],answer:1,explanation:'Q.S. al-Araf [7]: 180 memerintahkan bermohon kepada Allah dengan menyebut nama-nama-Nya yang baik, dan para ulama menjelaskan bahwa memilih nama yang sesuai dengan isi permohonan merupakan adab berdoa yang utama. Nama al-Karim sesuai untuk memohon kemurahan berupa rezeki karena mencakup makna Maha Pemurah, dan sesuai untuk memohon ampunan karena mencakup makna Maha Pemaaf yang menutupi kesalahan hamba. Q.S. an-Naml [27]: 40 menyebut bahwa barangsiapa bersyukur maka ia bersyukur untuk dirinya sendiri dan barangsiapa kufur maka sesungguhnya Tuhanku Maha Kaya lagi Maha Mulia. Q.S. az-Zumar [39]: 53 menyebut bahwa Allah mengampuni seluruh dosa bagi yang kembali kepada-Nya. Hadis memerintahkan mengikat kendaraan terlebih dahulu kemudian bertawakal, sehingga berdoa harus disertai usaha mencari rezeki yang halal dan taubat yang sungguh-sungguh.'},
{level:'HOTS',indicator:'Menganalisis hubungan al-Wakil dengan ikhtiar',text:'Sebagian orang memahami bahwa menyerahkan urusan kepada Allah berarti tidak perlu berusaha. Analisis yang paling tepat terhadap pemahaman tersebut adalah ...',options:['pemahaman itu keliru hanya karena usaha merupakan kewajiban yang ditetapkan masyarakat','pemahaman itu benar bagi orang yang imannya sangat kuat','keliru karena tawakal dilakukan setelah usaha yang sungguh-sungguh','pemahaman itu benar karena hasil telah ditentukan oleh Allah'],answer:2,explanation:'Q.S. Ali Imran [3]: 159 berbunyi dan bermusyawarahlah dengan mereka dalam urusan itu, kemudian apabila engkau telah membulatkan tekad maka bertawakallah kepada Allah. Urutan ayat menunjukkan bahwa musyawarah dan pembulatan tekad merupakan usaha yang mendahului tawakal. Hadis riwayat at-Tirmidzi menyebut bahwa seorang sahabat bertanya apakah ia mengikat kendaraannya lalu bertawakal atau melepaskannya lalu bertawakal, dan Rasulullah menjawab ikatlah kemudian bertawakallah. Hadis lain menyebut bahwa seandainya kalian bertawakal kepada Allah dengan sebenar-benar tawakal niscaya Allah memberi rezeki sebagaimana memberi rezeki burung yang pergi di pagi hari dalam keadaan lapar dan pulang di sore hari dalam keadaan kenyang, yang menggambarkan burung itu pergi mencari bukan berdiam di sarangnya. Q.S. al-Jumuah [62]: 10 memerintahkan bertebaran di muka bumi mencari karunia Allah setelah selesai salat. Karena itu tawakal selalu disertai ikhtiar.'},
{level:'HOTS',indicator:'Menentukan contoh memberi rasa aman di lingkungan sekolah',text:'Contoh perilaku yang paling tepat sebagai wujud memberi rasa aman di lingkungan sekolah adalah ...',options:['melaporkan setiap kesalahan teman kepada guru agar mereka dihukum','tidak ikut merundung, membela korban, dan menjaga rahasia teman','menghakimi sendiri teman yang dianggap bersalah agar jera','menjaga jarak dari teman yang sering bermasalah agar tidak terlibat'],answer:1,explanation:'Hadis menyebut bahwa seorang mukmin adalah orang yang manusia lain merasa aman terhadap harta dan jiwanya dari gangguannya, sehingga menjaga barang titipan dan tidak menyebarkan rahasia merupakan wujud memberi rasa aman. Hadis juga menyebut bahwa tidak beriman seseorang yang tetangganya tidak merasa aman dari gangguannya. Hadis menganjurkan menolong orang yang dizalimi dan yang menzalimi, dan menolong yang menzalimi berarti mencegahnya dari kezaliman. Hadis menyebut bahwa barangsiapa melihat kemungkaran hendaklah mengubahnya dengan tangan, apabila tidak mampu maka dengan lisan, dan apabila tidak mampu maka dengan hati. Hadis melarang menjerumuskan diri ke dalam kebinasaan, sehingga membela dilakukan dengan cara yang aman termasuk melalui laporan kepada guru. Hadis juga melarang memutuskan hubungan dengan sesama muslim lebih dari tiga hari. Karena itu menjaga jarak dari teman bermasalah atau menghakimi sendiri bukan cara yang tepat.'},
{level:'HOTS',indicator:'Menganalisis hikmah Allah disebut sebagai sebaik-baik pelindung',text:'Q.S. Ali Imran [3]: 173 menyebut bahwa cukuplah Allah menjadi penolong dan Allah merupakan sebaik-baik pelindung. Analisis yang paling tepat terhadap makna sebaik-baik pelindung adalah ...',options:['makna itu berarti perlindungan selain dari Allah tidak bermanfaat sama sekali','perlindungan Allah paling sempurna dan tidak disertai kelemahan','makna itu hanya berlaku bagi para nabi yang memperoleh perlindungan khusus','makna itu berarti manusia tidak perlu berusaha melindungi diri'],answer:1,explanation:'Q.S. Ali Imran [3]: 173 berbunyi yaitu orang-orang yang ketika ada yang mengatakan kepada mereka bahwa orang-orang telah berkumpul untuk menyerang kalian maka takutlah kepada mereka, tetapi justru hal itu menambah iman mereka dan mereka berkata cukuplah Allah menjadi penolong kami dan Allah merupakan sebaik-baik pelindung. Q.S. al-Anfal [8]: 40 menyebut bahwa Allah merupakan pelindung orang-orang beriman. Q.S. al-Anfal [8]: 62-63 menyebut bahwa apabila orang lain bermaksud menipu maka cukuplah Allah bagimu dan Dialah yang memperkuatmu dengan pertolongan-Nya. Hadis memerintahkan mengikat kendaraan terlebih dahulu kemudian bertawakal, yang menunjukkan bahwa ikhtiar tetap dilakukan. Hadis juga menganjurkan berlindung dari kejahatan makhluk melalui doa yang diajarkan. Karena itu perlindungan makhluk boleh dicari selama tidak melanggar ketentuan, tetapi hati tidak boleh menggantungkan diri kepadanya karena hanya perlindungan Allah yang sempurna.'},
{level:'HOTS',indicator:'Menentukan perilaku keteguhan dalam mempertahankan kejujuran',text:'Seorang pelajar mengetahui kebenaran tentang suatu peristiwa tetapi seluruh teman sekelompoknya menyepakati cerita yang tidak benar. Perilaku yang paling mencerminkan al-Matin adalah ...',options:['diam saja agar tidak menimbulkan konflik dalam kelompok','menyampaikan kebenaran dengan tenang dan bersedia menanggung akibatnya','menyampaikan kebenaran kepada seluruh teman di luar kelompok agar memperoleh dukungan','mengikuti cerita kelompok agar tidak dijauhi teman-temannya'],answer:1,explanation:'Q.S. al-Ahzab [33]: 39 memuji orang yang menyampaikan risalah Allah dan takut kepada-Nya serta tidak takut kepada siapa pun selain Allah. Hadis menyebut bahwa jihad yang paling utama adalah menyampaikan kata yang benar di hadapan penguasa yang zalim, yang menunjukkan keutamaan menyampaikan kebenaran walaupun berisiko. Hadis menyebut bahwa barangsiapa mencari ridha Allah walaupun manusia marah maka Allah mencukupkannya dari urusan manusia. Q.S. al-Baqarah [2]: 283 melarang menyembunyikan kesaksian dan menyebut bahwa barangsiapa menyembunyikannya maka hatinya berdosa. Hadis juga menyebut bahwa seorang muslim adalah orang yang kaum muslimin selamat dari gangguan lisannya, sehingga menyebarkan persoalan sebagai bahan pembicaraan bukan cara yang tepat. Q.S. an-Nisa [4]: 135 memerintahkan menjadi saksi karena Allah walaupun terhadap diri sendiri dan kerabat.'},
{level:'HOTS',indicator:'Menganalisis bahaya bergantung pada makhluk',text:'Seseorang menggantungkan harapan utamanya pada bantuan seorang pejabat sehingga ketika pejabat itu berpindah tugas maka seluruh harapannya runtuh. Analisis yang paling tepat terhadap bahaya ketergantungan tersebut adalah ...',options:['bahayanya hanya berupa kekecewaan yang sementara','kekecewaan berat, hilangnya kemuliaan diri, dan terhalang dari kecukupan Allah','tidak ada bahaya karena mencari bantuan merupakan hak setiap orang','bahayanya dapat dihindari dengan mencari pejabat lain yang lebih berkuasa'],answer:1,explanation:'Q.S. az-Zumar [39]: 3 menegaskan bahwa orang yang mengambil pelindung selain Allah beralasan agar pelindung itu mendekatkan mereka kepada Allah, dan Allah memberi keputusan di antara mereka tentang apa yang mereka perselisihkan. Q.S. al-Furqan [25]: 3 menyebut bahwa mereka mengambil tuhan-tuhan selain Allah yang tidak dapat menciptakan sesuatu pun sedangkan mereka diciptakan, dan tidak kuasa menolak bahaya dari diri mereka sendiri serta tidak kuasa mendatangkan kematian, kehidupan, dan kebangkitan. Hadis mengajarkan doa agar tidak menyerahkan urusan kepada diri sendiri sekejap mata pun dan tidak kepada seorang pun dari makhluk-Nya. Hadis juga menyebut bahwa apabila meminta maka mintalah kepada Allah dan apabila memohon pertolongan maka mohonlah pertolongan kepada Allah. Q.S. ath-Thalaq [65]: 3 menyebut bahwa barangsiapa bertawakal kepada Allah maka Dia akan mencukupkannya. Karena itu menggantungkan harapan utama pada makhluk menghasilkan kekecewaan yang berat dan kehilangan kemuliaan diri.'},
{level:'HOTS',indicator:'Menentukan contoh kemurahan kepada orang yang tidak dapat membalas',text:'Contoh perilaku yang paling tepat sebagai wujud kemurahan yang meneladani al-Karim adalah ...',options:['memberi kepada orang yang pernah memberi kepadanya agar seimbang','memberi dengan jumlah besar sekali saja agar diingat sebagai dermawan','memberi kepada yang tidak mampu membalas tanpa mengharap terima kasih','memberi bantuan kepada orang yang kedudukannya tinggi agar memperoleh imbalan'],answer:2,explanation:'Q.S. al-Lail [92]: 18-20 menggambarkan orang yang menafkahkan hartanya untuk menyucikan diri dan tidak ada seorang pun memberikan nikmat kepadanya yang harus dibalasnya, melainkan semata-mata mengharapkan wajah Tuhannya Yang Mahatinggi. Q.S. al-Insan [76]: 8-9 menggambarkan orang saleh yang memberi makan kepada orang miskin, anak yatim, dan tawanan, dan menyebut bahwa mereka tidak menghendaki balasan maupun ucapan terima kasih. Q.S. ad-Duha [93]: 9-10 memerintahkan tidak menghardik anak yatim dan tidak menolak orang yang meminta. Q.S. al-Maun [107]: 2-3 mengecam orang yang menghardik anak yatim dan tidak menganjurkan memberi makan orang miskin. Hadis menyebut bahwa sebaik-baik sedekah adalah yang diberikan ketika masih sehat dan kikir. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga memberi sekali dengan jumlah besar bukan pengganti keberlanjutan.'},
{level:'HOTS',indicator:'Menganalisis hubungan rasa aman dengan kepercayaan dalam masyarakat',text:'Masyarakat yang anggotanya saling memberi rasa aman mengalami kemajuan dalam kerja sama, sedangkan masyarakat yang dipenuhi kecurigaan mengalami kemunduran. Analisis yang paling tepat terhadap kenyataan tersebut adalah ...',options:['kemajuan masyarakat tidak berhubungan dengan rasa aman','rasa aman merupakan dasar kepercayaan dalam seluruh kerja sama','kemajuan masyarakat hanya ditentukan oleh kekayaan sumber daya','kecurigaan diperlukan agar masyarakat lebih berhati-hati sehingga justru menguntungkan'],answer:1,explanation:'Q.S. Quraisy [106]: 3-4 menyebut rasa aman dari ketakutan sebagai nikmat besar yang harus disyukuri dengan beribadah, yang menunjukkan bahwa rasa aman merupakan dasar bagi kegiatan hidup termasuk kegiatan ekonomi dan ibadah. Q.S. al-Anfal [8]: 25 memperingatkan tentang fitnah yang tidak hanya menimpa orang zalim melainkan seluruh masyarakat, sehingga kerusakan kepercayaan berdampak kolektif. Hadis menyebut bahwa seorang mukmin adalah orang yang manusia lain merasa aman terhadap harta dan jiwanya dari gangguannya. Hadis juga menyebut bahwa tanda hari kiamat di antaranya adalah hilangnya amanah dan dipercayanya orang yang tidak terpercaya. Hadis menganjurkan tolong-menolong dalam kebaikan. Q.S. al-Hujurat [49]: 12 melarang banyak berprasangka karena sebagian prasangka merupakan dosa. Karena itu rasa aman merupakan dasar kepercayaan yang menjadi syarat kerja sama, dan kecurigaan yang terus-menerus merusak tatanan sosial.'},
{level:'HOTS',indicator:'Menentukan sikap ketika usahanya tidak berhasil setelah bertawakal',text:'Seorang pelajar telah belajar dengan sungguh-sungguh dan menyerahkan hasilnya kepada Allah, tetapi nilainya tetap tidak memuaskan. Sikap yang paling tepat berdasarkan penghayatan al-Wakil adalah ...',options:['menyimpan kekecewaan dan berhenti belajar karena merasa usahanya tidak berguna','menerima hasil, mengevaluasi cara belajar, lalu berusaha lagi','berhenti bertawakal karena penyerahan kepada Allah tidak menghasilkan apa pun','menyalahkan guru karena dianggap tidak adil dalam menilai'],answer:1,explanation:'Hadis riwayat Muslim menyebut bahwa apabila seseorang tertimpa sesuatu maka jangan mengatakan seandainya aku melakukan demikian tentu hasilnya berbeda, karena ucapan seandainya membuka perbuatan setan, melainkan hendaklah mengatakan telah ditetapkan Allah dan apa yang dikehendaki-Nya terjadi. Q.S. al-Baqarah [2]: 216 menyebut bahwa boleh jadi manusia membenci sesuatu padahal sesuatu itu baik bagi mereka dan boleh jadi menyukai sesuatu padahal sesuatu itu buruk bagi mereka, sedangkan Allah mengetahui dan manusia tidak mengetahui. Q.S. ath-Thalaq [65]: 3 menyebut bahwa barangsiapa bertawakal kepada Allah maka Dia akan mencukupkannya. Q.S. asy-Syarh [94]: 5-6 menyebut bahwa bersama kesulitan terdapat kemudahan. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Karena itu menerima hasil dengan lapang dada, mengevaluasi, dan berusaha lagi merupakan wujud tawakal yang benar, sedangkan menyalahkan pihak lain atau berhenti berusaha merupakan bentuk keputusasaan yang dilarang.'},
{level:'HOTS',indicator:'Menganalisis hikmah kekuatan Allah yang tidak memerlukan bantuan makhluk',text:'Allah Maha Kuat dan Maha Kokoh tetapi tetap menugaskan malaikat untuk melaksanakan sebagian urusan-Nya dan memerintahkan manusia berusaha. Analisis yang paling tepat terhadap hikmah kenyataan tersebut adalah ...',options:['penugasan itu menunjukkan bahwa Allah memerlukan bantuan makhluk','penugasan itu memuliakan makhluk dan mendidik manusia agar berusaha','penugasan itu berarti usaha manusia menentukan hasil sehingga kekuatan Allah tidak berperan','penugasan itu berarti malaikat memiliki kekuatan yang setara dengan kekuatan Allah'],answer:1,explanation:'Q.S. Hud [11]: 6 menyebut bahwa tidak ada satu pun makhluk melata di bumi melainkan rezekinya ditanggung Allah, yang menunjukkan kekuasaan Allah yang menyeluruh. Q.S. Fathir [35]: 1 menyebut bahwa Allah menjadikan malaikat sebagai utusan yang memiliki sayap dua, tiga, dan empat serta menambah ciptaan-Nya sesuai kehendak-Nya. Q.S. al-Ankabut [29]: 6 menegaskan bahwa Allah benar-benar Maha Kaya dari seluruh alam. Q.S. al-Mulk [67]: 2 menyebut bahwa Allah menciptakan kematian dan kehidupan untuk menguji siapa yang paling baik amalnya, yang menunjukkan bahwa usaha manusia merupakan sarana ujian. Hadis menyebut bahwa mukmin yang kuat lebih baik dan lebih dicintai Allah daripada mukmin yang lemah. Q.S. adz-Dzariyat [51]: 58 menyebut bahwa Allah Maha Pemberi rezeki yang mempunyai kekuatan lagi sangat kokoh. Karena itu penugasan malaikat dan perintah berusaha merupakan bentuk pemuliaan makhluk dan sarana pendidikan, bukan karena keperluan Allah.'},
{level:'HOTS',indicator:'Menentukan perilaku kemurahan dalam keluarga',text:'Perilaku yang paling tepat sebagai wujud kemurahan dalam keluarga yang meneladani al-Karim adalah ...',options:['mudah memaafkan, berbagi, dan tidak menghitung-hitung jasa','memberi uang saku yang besar agar anak merasa dimanjakan','menghitung setiap pemberian kepada anggota keluarga agar mereka tahu pengorbanan orang tua','memberi seluruh keinginan anggota keluarga agar tidak ada yang merasa kekurangan'],answer:0,explanation:'Hadis menyebut bahwa Allah Maha Pemurah dan menyukai orang yang pemurah serta menyukai akhlak yang mulia. Hadis juga menyebut bahwa sebaik-baik kalian adalah yang paling baik terhadap keluarganya. Hadis menyebut bahwa senyum kepada saudaramu merupakan sedekah, sehingga kemurahan tidak terbatas pada harta. Q.S. al-Baqarah [2]: 264 melarang menghilangkan pahala pemberian dengan menyebut-nyebutnya dan menyakiti perasaan penerima, sehingga menghitung pemberian kepada anggota keluarga merupakan perbuatan yang mengurangi nilai pemberian. Hadis juga menyebut bahwa tidak ada yang memaafkan melainkan Allah menambah kemuliaannya. Q.S. at-Taghabun [64]: 14 menganjurkan memaafkan, menutupi, dan mengampuni kesalahan keluarga. Adapun memberi seluruh keinginan anggota keluarga bukan kemurahan melainkan pembiaran yang dapat menumbuhkan sikap manja dan boros, sebab Q.S. al-Isra [17]: 26-27 melarang pemborosan.'},
{level:'HOTS',indicator:'Menganalisis kedudukan keempat nama dalam menghadapi persoalan hidup',text:'Seorang pelajar menghadapi persoalan berupa kesulitan ekonomi keluarga yang memengaruhi kelanjutan sekolahnya. Analisis yang paling tepat terhadap penerapan keempat nama dalam menghadapi persoalan tersebut adalah ...',options:['memohon dengan keempat nama itu disertai usaha mencari jalan keluar','menyerahkan seluruh persoalan kepada orang tua karena merupakan tanggung jawab mereka','berhenti sekolah sementara agar dapat bekerja membantu keluarga tanpa mempertimbangkan akibat jangka panjang','cukup berdoa dengan menyebut keempat nama tanpa melakukan usaha lain'],answer:0,explanation:'Q.S. al-Araf [7]: 180 memerintahkan bermohon kepada Allah dengan menyebut nama-nama-Nya yang baik, dan memilih nama yang sesuai dengan isi permohonan merupakan adab berdoa yang utama. Q.S. Ali Imran [3]: 159 memerintahkan bermusyawarah kemudian bertawakal setelah membulatkan tekad, sehingga usaha mencari jalan seperti beasiswa atau bantuan merupakan bagian dari ikhtiar yang mendahului tawakal. Hadis menyebut bahwa Allah tidak menurunkan kesulitan melainkan menurunkan pula jalan keluarnya. Q.S. at-Talaq [65]: 2-3 menyebut bahwa barangsiapa bertakwa kepada Allah maka Dia mengadakan baginya jalan keluar dan memberi rezeki dari arah yang tidak disangka. Q.S. al-Mujadilah [58]: 11 menyebut keutamaan ilmu sehingga mempertahankan pendidikan merupakan kepentingan jangka panjang. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Karena itu keempat nama diterapkan dalam doa disertai usaha nyata, bukan sebagai pengganti usaha.'},
{level:'HOTS',indicator:'Menentukan perilaku kemurahan dalam pergaulan dengan teman',text:'Perilaku yang paling tepat sebagai wujud kemurahan dalam pergaulan dengan teman yang meneladani al-Karim adalah ...',options:['memberi seluruh yang diminta teman agar dianggap baik hati','tidak memberi apa pun karena memberi dapat membuat teman menjadi manja','mudah memaafkan, berbagi, menepati janji, dan tidak memutus hubungan','memberi kepada teman yang diperkirakan akan membalas dengan jumlah lebih besar'],answer:2,explanation:'Hadis menyebut bahwa Allah Maha Pemurah dan menyukai orang yang pemurah. Hadis juga menyebut bahwa hadiah dapat menumbuhkan kasih sayang dan menghilangkan permusuhan. Hadis lain menyebut bahwa tidak ada yang memaafkan melainkan Allah menambah kemuliaannya. Hadis juga menyebut bahwa seorang muslim adalah saudara bagi muslim yang lain sehingga tidak menzaliminya dan tidak menyerahkannya kepada musuh. Hadis melarang memutuskan hubungan dengan sesama muslim lebih dari tiga hari dan menyebut bahwa yang terbaik di antara keduanya adalah yang memulai salam. Q.S. al-Baqarah [2]: 264 melarang menghilangkan pahala pemberian dengan menyebut-nyebutnya, yang menjadi dasar tidak menghitung-hitung pemberian dalam pergaulan. Adapun memberi seluruh yang diminta teman bukan kemurahan melainkan dapat menumbuhkan ketergantungan, dan tidak memberi sama sekali merupakan kekikiran yang dilarang.'},
{level:'HOTS',indicator:'Menganalisis hikmah nama al-Mumin menuntut penjagaan amanah',text:'Nama al-Mumin berkaitan dengan pemberian rasa aman. Analisis yang paling tepat terhadap hubungan nama tersebut dengan kewajiban menjaga amanah adalah ...',options:['rasa aman terwujud ketika setiap orang menjaga amanah','amanah hanya berkaitan dengan harta sehingga tidak berhubungan dengan rasa aman','rasa aman merupakan tanggung jawab pihak berwenang bukan tanggung jawab pribadi','keduanya tidak berhubungan karena amanah merupakan persoalan muamalah'],answer:0,explanation:'Hadis menyebut bahwa seorang mukmin adalah orang yang manusia lain merasa aman terhadap harta dan jiwanya dari gangguannya, sehingga menjaga amanah merupakan syarat terwujudnya rasa aman. Hadis juga menyebut bahwa tidak ada iman bagi orang yang tidak amanah dan tidak ada agama bagi orang yang tidak menepati janji. Q.S. al-Anfal [8]: 27 melarang mengkhianati Allah, Rasul, dan amanah yang dipercayakan. Hadis menyebut bahwa tanda hari kiamat di antaranya adalah hilangnya amanah dan dipercayanya orang yang tidak terpercaya. Q.S. al-Muminun [23]: 8 menyebut bahwa orang beriman memelihara amanat dan janjinya. Hadis juga menyebut bahwa setiap orang merupakan pemimpin dan akan ditanya tentang apa yang dipimpinnya. Karena itu amanah mencakup seluruh nikmat dan tanggung jawab, dan menjaganya merupakan wujud nyata memberi rasa aman kepada orang lain.'},
{level:'HOTS',indicator:'Menentukan contoh keteguhan dalam menghadapi tekanan kelompok',text:'Sebuah kelompok teman mengajak seorang pelajar untuk tidak mengikuti kegiatan keagamaan di sekolah dan mengancam akan menjauhinya. Contoh keteguhan yang paling tepat adalah ...',options:['menentang kelompok itu secara terbuka agar kelompok lain melihat keberaniannya','tetap mengikuti kegiatan dengan tenang tanpa menantang kelompok itu','mengikuti ajakan kelompok agar tidak dijauhi teman-temannya','berhenti mengikuti kegiatan keagamaan untuk sementara agar kelompok itu puas'],answer:1,explanation:'Q.S. al-Ahzab [33]: 39 memuji orang yang takut kepada Allah dan tidak takut kepada siapa pun selain Allah. Hadis menyebut bahwa barangsiapa mencari ridha Allah walaupun manusia marah maka Allah mencukupkannya dari urusan manusia, dan barangsiapa mencari ridha manusia dengan kemurkaan Allah maka Allah menyerahkannya kepada manusia. Q.S. al-Kahfi [18]: 28 memerintahkan menahan diri bersama orang yang menyeru Tuhan pagi dan petang serta tidak menuruti orang yang dilalaikan oleh hawa nafsunya. Hadis melarang memutuskan hubungan dengan sesama muslim lebih dari tiga hari, sehingga tetap berhubungan dalam urusan yang baik merupakan adab. Hadis juga menyebut bahwa tidaklah kelembutan ada pada sesuatu melainkan ia menghiasinya, sehingga menjelaskan alasan dilakukan dengan tenang bukan dengan tantangan. Hadis menganjurkan mendoakan kebaikan bagi orang yang belum memperoleh hidayah.'},
{level:'HOTS',indicator:'Menganalisis hikmah Allah memberi tanpa diminta',text:'Allah memberi rezeki kepada seluruh makhluk tanpa mereka memintanya, tetapi tetap memerintahkan manusia berdoa. Analisis yang paling tepat terhadap hikmah kenyataan tersebut adalah ...',options:['pemberian tanpa diminta menunjukkan kemurahan, sedangkan doa mengangkat kedudukan hamba','perintah berdoa tidak berguna karena Allah telah memberi tanpa diminta','berdoa hanya berguna untuk memperoleh apa yang belum diberikan Allah','pemberian tanpa diminta berarti Allah tidak memerlukan doa sehingga berdoa merupakan kebiasaan yang tidak bernilai'],answer:0,explanation:'Q.S. Ibrahim [14]: 34 menyebut bahwa Allah telah memberikan kepada manusia segala apa yang dimintanya dan apabila menghitung nikmat Allah niscaya tidak mampu menghitungnya. Q.S. Ghafir [40]: 60 memerintahkan berdoa kepada Allah dengan jaminan bahwa Dia akan mengabulkan, serta menyebut bahwa orang yang menyombongkan diri dari beribadah kepada-Nya akan masuk neraka dalam keadaan hina, yang menunjukkan bahwa doa merupakan ibadah dan meninggalkannya merupakan kesombongan. Hadis menyebut bahwa doa merupakan ibadah. Hadis juga menyebut bahwa tidak ada sesuatu yang lebih mulia di sisi Allah selain doa. Hadis qudsi menyebut bahwa Allah sesuai dengan prasangka hamba-Nya. Karena itu pemberian tanpa diminta menunjukkan kemurahan Allah yang luas, sedangkan perintah berdoa merupakan sarana manusia memperoleh kemuliaan sebagai hamba yang mengakui ketergantungannya kepada Allah.'},
{level:'HOTS',indicator:'Menentukan perilaku memberi rasa aman dalam penggunaan media sosial',text:'Perilaku yang paling tepat sebagai wujud memberi rasa aman dalam penggunaan media sosial adalah ...',options:['menyebarkan informasi yang belum jelas kebenarannya agar menjadi yang pertama menyampaikan','menghapus seluruh akun media sosial karena media sosial selalu berbahaya','menggunakan nama samaran agar bebas menulis apa pun','memeriksa kebenaran informasi dan tidak mengunggah konten yang mempermalukan'],answer:3,explanation:'Q.S. al-Hujurat [49]: 6 memerintahkan meneliti kebenaran berita yang dibawa agar tidak menimpakan musibah kepada suatu kaum karena ketidaktahuan. Q.S. al-Isra [17]: 36 melarang mengikuti sesuatu yang tidak diketahui dan menyebut bahwa pendengaran, penglihatan, dan hati seluruhnya akan dimintai pertanggungjawaban. Hadis menyebut bahwa seorang muslim adalah orang yang kaum muslimin selamat dari gangguan lisan dan tangannya, dan dalam konteks media sosial lisan mencakup tulisan. Hadis juga menyebut bahwa barangsiapa menutupi aib seorang muslim maka Allah menutupi aibnya, sehingga menjaga rahasia dan foto pribadi teman merupakan wujud penjagaan amanah. Hadis menyebut bahwa cukuplah seseorang dianggap berdusta apabila menyampaikan setiap yang didengarnya. Hadis juga menganjurkan melaporkan kemungkaran kepada pihak yang berwenang apabila tidak mampu mengubahnya sendiri. Karena itu menggunakan nama samaran untuk bebas menulis merupakan bentuk lepas tanggung jawab, sedangkan menghapus seluruh akun bukan penyelesaian apabila media sosial dapat digunakan untuk kebaikan.'},
{level:'HOTS',indicator:'Menganalisis hubungan al-Karim dengan sikap tidak cepat menghakimi',text:'Allah Maha Pemurah dan menutupi kesalahan hamba-Nya serta menangguhkan hukuman walaupun Dia mampu menyegerakan. Analisis yang paling tepat terhadap pengaruh penghayatan tersebut dalam menyikapi kesalahan orang lain adalah ...',options:['tidak cepat menghakimi dan memberi kesempatan memperbaiki diri','kesalahan orang lain harus segera diumumkan agar masyarakat waspada','kesalahan orang lain harus dihukum seberat mungkin agar menjadi pelajaran','penghayatan terhadap kemurahan Allah berarti seluruh kesalahan orang lain harus dibiarkan tanpa nasihat'],answer:0,explanation:'Q.S. Fathir [35]: 45 menyebut bahwa kalau sekiranya Allah menyiksa manusia disebabkan usahanya niscaya Dia tidak akan meninggalkan di atas permukaan bumi suatu makhluk yang melata pun, akan tetapi Allah menangguhkan mereka sampai waktu yang tertentu. Hadis menyebut bahwa barangsiapa menutupi aib seorang muslim maka Allah menutupi aibnya di dunia dan akhirat. Hadis juga menyebut bahwa apabila seseorang berbuat salah maka hendaklah dinasihati secara pribadi karena nasihat di depan umum terasa seperti penghinaan. Q.S. an-Nur [24]: 22 menganjurkan memaafkan dan berlapang dada. Hadis menyebut bahwa seorang mukmin merupakan cermin bagi saudaranya, yang berarti menasihati dengan cara yang memperbaiki bukan mempermalukan. Hadis juga menganjurkan menolong orang yang menzalimi dengan mencegahnya dari kezaliman. Karena itu membiarkan kesalahan tanpa nasihat bukan kemurahan melainkan pembiaran, sedangkan mengumumkan kesalahan merupakan pelanggaran terhadap penjagaan aib.'},
{level:'HOTS',indicator:'Menentukan contoh penyerahan urusan kepada Allah dalam persoalan keluarga',text:'Keluarga seorang pelajar menghadapi persoalan yang tidak mampu diselesaikannya sendiri. Contoh perilaku yang paling tepat berdasarkan penghayatan al-Wakil adalah ...',options:['bermusyawarah, menempuh cara halal, berdoa, lalu menyerahkan hasilnya','mencari jalan keluar dengan cara apa pun termasuk meminta bantuan dukun karena keadaan sudah mendesak','menyerahkan seluruh persoalan kepada orang tua karena merupakan tanggung jawab orang tua','menyimpan persoalan itu sendiri agar keluarga tidak terbebani'],answer:0,explanation:'Q.S. asy-Syura [42]: 38 menyebut bahwa urusan orang beriman diselesaikan dengan musyawarah. Q.S. Ali Imran [3]: 159 memerintahkan bermusyawarah kemudian bertawakal setelah membulatkan tekad. Q.S. an-Nahl [16]: 43 memerintahkan bertanya kepada ahli pengetahuan apabila tidak mengetahui. Hadis memerintahkan mengikat kendaraan terlebih dahulu kemudian bertawakal. Hadis melarang mendatangi tukang ramal dan menyebut bahwa barangsiada mendatangi dukun lalu membenarkan ucapannya maka ia telah ingkar kepada apa yang diturunkan kepada Muhammad. Q.S. ath-Thalaq [65]: 2-3 menyebut bahwa barangsiapa bertakwa kepada Allah maka Dia mengadakan baginya jalan keluar dan memberi rezeki dari arah yang tidak disangka. Hadis juga menyebut bahwa istigfar merupakan jalan keluar dari setiap kesempitan. Karena itu musyawarah, meminta nasihat, menempuh cara halal, berdoa, dan menyerahkan hasil kepada Allah merupakan rangkaian perilaku yang tepat.'},
{level:'HOTS',indicator:'Menganalisis hikmah keteguhan dalam kebaikan yang tidak segera menghasilkan',text:'Seorang pelajar terus menasihati temannya dengan cara yang baik tetapi temannya belum berubah. Analisis yang paling tepat terhadap hikmah keteguhan dalam kebaikan yang hasilnya tidak segera terlihat adalah ...',options:['kewajiban menyampaikan kebaikan, sedangkan hidayah milik Allah','keteguhan itu tidak berguna karena hasilnya tidak terlihat','hasil yang tidak terlihat menunjukkan bahwa cara nasihat harus diganti dengan cara yang lebih keras','keteguhan itu berarti nasihat harus diulang terus menerus walaupun mengganggu'],answer:0,explanation:'Q.S. al-Qashash [28]: 56 menegaskan bahwa sesungguhnya engkau tidak dapat memberi petunjuk kepada orang yang engkau cintai tetapi Allah memberi petunjuk kepada siapa yang dikehendaki-Nya, dan Allah lebih mengetahui tentang orang-orang yang mau menerima petunjuk. Q.S. al-Ghasyiyah [88]: 21-22 memerintahkan memberi peringatan karena tugas hanyalah memberi peringatan bukan memaksa. Hadis menyebut bahwa sampaikanlah walaupun satu ayat. Hadis juga menyebut bahwa barangsiapa menunjukkan kepada kebaikan maka ia memperoleh pahala seperti pahala orang yang mengerjakannya. Q.S. an-Nahl [16]: 125 memerintahkan menyeru dengan hikmah dan pelajaran yang baik serta berdialog dengan cara yang terbaik. Hadis menyebut bahwa tidaklah kelembutan ada pada sesuatu melainkan ia menghiasinya, sehingga cara yang lebih keras bukan penyelesaian. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit. Karena itu keteguhan dalam menyampaikan kebaikan tetap bernilai walaupun hasilnya tidak segera terlihat.'},
{level:'HOTS',indicator:'Menentukan perilaku kemurahan dalam keadaan sendiri sedang kekurangan',text:'Seorang pelajar memiliki bekal yang terbatas lalu melihat temannya tidak membawa bekal. Perilaku yang paling tepat adalah ...',options:['memberi uang kepada temannya di depan teman-teman lain agar dikenal sebagai orang dermawan','tidak berbagi karena bekalnya sendiri terbatas','berbagi sesuai kemampuan tanpa mempermalukan temannya','memberikan seluruh bekalnya lalu pulang tanpa makan karena itu lebih mulia'],answer:2,explanation:'Q.S. Ali Imran [3]: 92 menyebut bahwa kamu sekali-kali tidak akan memperoleh kebajikan yang sempurna sebelum menafkahkan sebagian harta yang kamu cintai. Hadis menyebut bahwa sebaik-baik sedekah adalah yang diberikan ketika masih sehat dan kikir serta mengharapkan kekayaan. Q.S. al-Hasyr [59]: 9 memuji orang yang mengutamakan orang lain atas dirinya walaupun dalam keadaan memerlukan, dan menyebut bahwa siapa yang dipelihara dari kekikiran maka mereka itulah orang yang beruntung. Q.S. al-Baqarah [2]: 264 melarang menghilangkan pahala sedekah dengan menyebut-nyebutnya dan menyakiti perasaan penerima. Hadis menyebut bahwa barangsiapa menutupi aib seorang muslim maka Allah menutupi aibnya. Q.S. al-Baqarah [2]: 286 menegaskan bahwa Allah tidak membebani seseorang melainkan sesuai kesanggupannya, sehingga berbagi sesuai kemampuan sudah mencukupi dan tidak perlu mengorbankan seluruh bekal apabila membahayakan diri. Karena itu berbagi sesuai kemampuan dengan cara yang menjaga kehormatan penerima merupakan perilaku yang paling tepat.'},
{level:'HOTS',indicator:'Menganalisis hubungan keempat asmaul husna dengan kesehatan jiwa',text:'Penghayatan terhadap al-Karim, al-Mumin, al-Wakil, dan al-Matin menghasilkan keadaan jiwa yang sehat. Analisis yang paling tepat terhadap hubungan tersebut adalah ...',options:['hubungan itu tidak ada karena asmaul husna merupakan persoalan keyakinan bukan keadaan jiwa','penghayatan keempatnya berarti tidak pernah merasakan kesedihan dan kekhawatiran','kesehatan jiwa hanya dapat diperoleh melalui bantuan tenaga profesional','keempatnya menghilangkan kekikiran, kecurigaan, kecemasan, dan keraguan'],answer:3,explanation:'Q.S. ar-Rad [28]: 28 menegaskan bahwa hati menjadi tenteram dengan mengingat Allah. Q.S. ath-Thalaq [65]: 3 menyebut bahwa barangsiapa bertawakal kepada Allah maka Dia akan mencukupkannya, yang menghilangkan kecemasan terhadap hasil. Hadis menyebut bahwa Allah Maha Pemurah dan menyukai orang yang pemurah, dan kemurahan hati menghilangkan kekikiran yang merupakan sumber kecemasan terhadap kehilangan. Q.S. al-Anam [6]: 82 menyebut bahwa orang yang beriman dan tidak mencampur imannya dengan kezaliman memperoleh keamanan, yang menghilangkan kecurigaan dan permusuhan. Q.S. al-Ahzab [33]: 23 memuji keteguhan orang mukmin yang tidak mengubah janjinya, yang menghilangkan keraguan. Hadis juga menyebut bahwa sungguh mengagumkan urusan orang beriman karena seluruh urusannya baik baginya. Adapun kesedihan dan kekhawatiran tetap dirasakan karena merupakan perasaan manusiawi, tetapi tidak menguasai dan tidak berubah menjadi keputusasaan.'},
{level:'HOTS',indicator:'Menentukan cara menghafal dan mengamalkan asmaul husna',text:'Cara menghafal dan mengamalkan asmaul husna yang paling tepat adalah ...',options:['menyebut seluruh nama dalam setiap doa agar tidak ada yang terlewat','menghafal nama yang mudah diucapkan saja tanpa memahami maknanya','menghafal bertahap, memahami makna, berdoa, dan meneladaninya','menghafal seluruh nama dengan urutan yang benar lalu menganggap tugas telah selesai'],answer:2,explanation:'Hadis riwayat al-Bukhari dan Muslim menyebut bahwa Allah memiliki sembilan puluh sembilan nama dan barangsiapa menghafalnya akan masuk surga, dan para ulama menjelaskan bahwa menghafal dalam hadis itu mencakup menghafal lafaznya, memahami maknanya, serta beramal sesuai tuntutannya. Q.S. al-Araf [7]: 180 memerintahkan bermohon kepada Allah dengan menyebut nama-nama-Nya yang baik, yang menjadi dasar memilih nama yang sesuai dengan permohonan. Hadis menyebut bahwa Allah Maha Pemurah dan menyukai orang yang pemurah, yang menjadi dasar meneladani makna nama dalam batas kemanusiaan. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga menghafal secara bertahap dan menyebut nama dalam zikir harian merupakan cara yang berkelanjutan. Q.S. Muhammad [47]: 24 memerintahkan merenungkan Al-Quran, yang menjadi dasar memahami makna setiap nama beserta dalilnya. Karena itu menghafal tanpa memahami atau memilih yang mudah saja tidak memenuhi tuntutan hadis.'},
{level:'HOTS',indicator:'Menganalisis hikmah disebutkannya al-Matin sebagai pemberi kekuatan',text:'Q.S. adz-Dzariyat [51]: 58 menyebut Allah sebagai pemberi rezeki yang mempunyai kekuatan lagi sangat kokoh. Analisis yang paling tepat terhadap hikmah digandengkannya kekuatan dengan pemberian rezeki dalam ayat tersebut adalah ...',options:['penggandengan itu berarti manusia tidak perlu bekerja karena rezeki dijamin','penggandengan itu menunjukkan bahwa kekuatan Allah terbatas pada urusan rezeki','penggandengan itu menunjukkan bahwa rezeki hanya diberikan kepada yang kuat','jaminan rezeki ditopang kekuatan yang tidak terbatas'],answer:3,explanation:'Q.S. adz-Dzariyat [51]: 58 berbunyi sesungguhnya Allah Dialah Maha Pemberi rezeki yang mempunyai kekuatan lagi sangat kokoh. Q.S. Hud [11]: 6 menyebut bahwa tidak ada satu pun makhluk melata di bumi melainkan rezekinya ditanggung Allah dan Dia mengetahui tempat berdiam dan tempat penyimpanannya. Q.S. al-Ankabut [29]: 60 menyebut bahwa berapa banyak makhluk bergerak yang tidak membawa rezekinya sendiri, tetapi Allah memberi rezeki kepada mereka dan kepada kalian, dan Dia Maha Mendengar lagi Maha Mengetahui. Hadis menyebut bahwa seandainya kalian bertawakal kepada Allah dengan sebenar-benar tawakal niscaya Allah memberi rezeki sebagaimana memberi rezeki burung yang pergi di pagi hari dalam keadaan lapar dan pulang di sore hari dalam keadaan kenyang, yang menggambarkan burung itu pergi mencari rezeki. Q.S. al-Jumuah [62]: 10 memerintahkan bertebaran di muka bumi mencari karunia Allah. Karena itu jaminan rezeki yang ditopang kekuatan kokoh menjadi dasar ketenangan, tetapi tetap menuntut usaha.'},
{level:'HOTS',indicator:'Menentukan perilaku memberi rasa aman kepada orang yang berbeda pendapat',text:'Seorang pelajar berbeda pendapat dengan temannya dalam musyawarah kelas secara tajam. Perilaku yang paling tepat sebagai wujud memberi rasa aman adalah ...',options:['menerima pendapat teman tetapi menceritakan ketidaksetujuannya kepada teman lain setelah musyawarah','menyampaikan perbedaan pendapat dengan menyerang pribadi teman agar pendapatnya ditolak','tidak menyampaikan pendapat agar tidak terjadi konflik','menyampaikan perbedaan dengan tenang dan berfokus pada pokok persoalan'],answer:3,explanation:'Q.S. asy-Syura [42]: 38 menyebut bahwa urusan orang beriman diselesaikan dengan musyawarah. Q.S. Ali Imran [3]: 159 memerintahkan bermusyawarah kemudian apabila telah membulatkan tekad maka bertawakallah kepada Allah, serta menyebut bahwa kelembutan merupakan sebab orang berkumpul sedangkan kekerasan merupakan sebab mereka menjauh. Hadis menyebut bahwa seorang mukmin adalah orang yang manusia lain merasa aman terhadap harta dan jiwanya dari gangguannya, sehingga menyampaikan pendapat tanpa menyerang pribadi merupakan wujud memberi rasa aman. Q.S. al-Hujurat [49]: 11 melarang suatu kaum mengolok-olok kaum yang lain. Hadis melarang memutuskan hubungan dengan sesama muslim lebih dari tiga hari. Q.S. al-Hujurat [49]: 12 melarang ghibah, sehingga menceritakan ketidaksetujuan kepada teman lain setelah musyawarah merupakan bentuk ghibah yang dilarang.'},
{level:'HOTS',indicator:'Menganalisis hikmah kemurahan Allah yang mendahului kemurkaan-Nya',text:'Hadis qudsi menyebut bahwa rahmat Allah mendahului kemurkaan-Nya. Analisis yang paling tepat terhadap hikmah kenyataan tersebut bagi orang yang pernah berbuat dosa besar adalah ...',options:['hikmahnya bahwa rahmat Allah diberikan kepada seluruh makhluk tanpa memandang amal','pintu taubat selalu terbuka tetapi bukan alasan untuk bermaksiat','hikmahnya bahwa dosa besar tidak akan dihukum karena rahmat mendahului kemurkaan','hikmahnya bahwa kemurkaan Allah tidak pernah terjadi sehingga tidak perlu ditakuti'],answer:1,explanation:'Hadis qudsi riwayat al-Bukhari dan Muslim menyebut bahwa Allah menetapkan rahmat dalam kitab yang ada di sisi-Nya di atas Arsy bahwa rahmat-Ku mendahului kemurkaan-Ku. Q.S. az-Zumar [39]: 53 melarang berputus asa dari rahmat Allah dan menyebut bahwa Allah mengampuni seluruh dosa bagi yang kembali kepada-Nya. Q.S. an-Nisa [4]: 17-18 menyebut bahwa taubat diterima dari orang yang berbuat kejahatan karena ketidaktahuan lalu segera bertaubat, dan bahwa taubat tidak diterima dari orang yang terus berbuat kejahatan hingga kematian datang. Hadis menyebut bahwa Allah membentangkan tangan-Nya pada malam hari untuk menerima taubat orang yang berbuat dosa pada siang hari. Hadis qudsi juga menyebut bahwa Allah Maha Adil dan mengharamkan kezaliman atas diri-Nya. Q.S. al-Araf [7]: 99 memperingatkan agar tidak merasa aman dari azab Allah karena yang merasa aman hanyalah kaum yang merugi. Karena itu rahmat yang mendahului kemurkaan merupakan dasar harapan bagi orang yang bertaubat, bukan alasan untuk terus bermaksiat.'},
{level:'HOTS',indicator:'Menentukan perilaku keteguhan dalam menjaga ibadah ketika bepergian',text:'Seorang pelajar mengikuti kegiatan di luar kota yang jadwalnya padat sehingga waktu salat menjadi sempit. Perilaku yang paling mencerminkan al-Matin adalah ...',options:['tidak melaksanakan salat karena kegiatan merupakan kewajiban yang harus dipenuhi','merencanakan jadwal dengan memperhatikan waktu salat dan menjamaknya bila dibolehkan','menunda salat hingga pulang ke rumah walaupun waktunya telah habis','melaksanakan salat pada waktu yang paling longgar walaupun bukan waktunya'],answer:1,explanation:'Q.S. al-Baqarah [2]: 238 memerintahkan memelihara salat-salat terutama salat wusta dan berdiri untuk Allah dengan khusyuk. Q.S. an-Nisa [4]: 103 menyebut bahwa salat merupakan kewajiban yang ditentukan waktunya atas orang beriman. Hadis menyebut bahwa amal yang paling dicintai Allah adalah salat pada waktunya. Hadis juga menyebut bahwa Rasulullah menjamak salat ketika bepergian, dan Q.S. al-Baqarah [2]: 185 menyebut bahwa Allah menghendaki kemudahan, sehingga memanfaatkan keringanan yang dibolehkan merupakan bagian dari ketaatan. Hadis menyebut bahwa tidak ada ketaatan kepada makhluk dalam bermaksiat kepada Pencipta, sehingga jadwal kegiatan tidak menjadi alasan meninggalkan salat. Q.S. al-Ahzab [33]: 39 memuji orang yang takut kepada Allah dan tidak takut kepada siapa pun selain Allah. Hadis juga menyebut bahwa malu merupakan bagian dari iman tetapi tidak menghalangi dari kebenaran. Karena itu menunda salat hingga habis waktunya atau tidak melaksanakannya bukan perilaku yang tepat.'},
{level:'HOTS',indicator:'Menganalisis hubungan kemurahan dengan tidak pelit dalam berbagi ilmu',text:'Seorang pelajar memahami suatu materi tetapi temannya tidak memahami dan memintanya menjelaskan. Analisis yang paling tepat terhadap kedudukan berbagi ilmu sebagai wujud kemurahan adalah ...',options:['berbagi ilmu tidak termasuk kemurahan karena ilmu bukan harta','berbagi ilmu sebaiknya ditunda agar teman berusaha memahami sendiri','berbagi ilmu merupakan kemurahan yang paling bernilai dan menjadi amal jariyah','berbagi ilmu hanya bermanfaat bagi yang menerima sehingga tidak bernilai bagi pemberi'],answer:2,explanation:'Hadis menyebut bahwa apabila seseorang meninggal maka terputuslah amalnya kecuali tiga perkara yaitu sedekah jariyah, ilmu yang bermanfaat, dan anak saleh yang mendoakannya, sehingga ilmu yang diajarkan merupakan amal yang terus mengalir. Hadis juga menyebut bahwa barangsiapa menunjukkan kepada kebaikan maka ia memperoleh pahala seperti pahala orang yang mengerjakannya. Hadis menyebut bahwa barangsiapa ditanya tentang ilmu lalu menyembunyikannya maka akan dipasang padanya kendali dari api pada hari kiamat. Hadis menyebut bahwa Allah Maha Pemurah dan menyukai orang yang pemurah serta menyukai akhlak yang mulia. Q.S. al-Mujadilah [58]: 11 menyebut bahwa Allah mengangkat derajat orang yang diberi ilmu. Hadis juga menyebut bahwa sebaik-baik manusia adalah yang paling bermanfaat bagi manusia. Karena itu berbagi ilmu merupakan bentuk kemurahan yang bernilai tinggi, dan menahannya merupakan kekikiran yang diancam.'},
{level:'HOTS',indicator:'Menentukan contoh memberi rasa aman kepada orang yang lebih lemah',text:'Contoh perilaku yang paling tepat sebagai wujud memberi rasa aman kepada orang yang lebih lemah adalah ...',options:['menolong orang yang lebih lemah hanya ketika ada orang yang melihat agar dipuji','menghindari orang yang lebih lemah karena tidak dapat memberi keuntungan','melindungi yang lemah dan tidak memanfaatkan kelemahannya','memberi uang kepada orang yang lebih lemah agar mereka tidak mengganggu'],answer:2,explanation:'Hadis menyebut bahwa tidak termasuk golongan Rasulullah orang yang tidak menghormati orang yang lebih tua dan tidak menyayangi yang lebih muda serta tidak mengetahui hak orang alim. Hadis juga menyebut bahwa Allah senantiasa menolong seorang hamba selama hamba itu menolong saudaranya. Hadis menyebut bahwa seorang mukmin adalah orang yang manusia lain merasa aman terhadap harta dan jiwanya dari gangguannya, sehingga memanfaatkan kelemahan orang lain merupakan pelanggaran terhadap rasa aman. Q.S. ad-Duha [93]: 9-10 memerintahkan tidak menghardik anak yatim dan tidak menolak orang yang meminta. Q.S. al-Maun [107]: 2-3 mengecam orang yang menghardik anak yatim dan tidak menganjurkan memberi makan orang miskin. Hadis juga menyebut bahwa orang yang membantu janda dan orang miskin seperti orang yang berjihad di jalan Allah. Hadis qudsi menyebut bahwa Allah Maha Cukup dari sekutu sehingga amal yang dikerjakan untuk dilihat manusia ditolak. Karena itu menolong hanya ketika ada yang melihat merupakan riya yang mengancam pahala amal.'},
{level:'HOTS',indicator:'Menganalisis hikmah keteguhan yang disertai kelembutan',text:'Islam mengajarkan keteguhan dalam memegang prinsip sekaligus kelembutan dalam menyampaikan. Analisis yang paling tepat terhadap hikmah penggabungan keduanya adalah ...',options:['penggabungan itu hanya berlaku ketika berhadapan dengan orang yang lebih tua','penggabungan itu berarti kelembutan lebih utama daripada keteguhan','penggabungan itu berarti keteguhan dapat dikompromikan dengan kelembutan','keteguhan yang disampaikan dengan lembut lebih mudah diterima'],answer:3,explanation:'Q.S. Ali Imran [3]: 159 menyebut bahwa dengan rahmat Allah engkau berlaku lemah lembut terhadap mereka, dan sekiranya engkau bersikap keras dan berhati kasar tentu mereka akan menjauh dari sekitarmu, kemudian memerintahkan memaafkan, memohonkan ampunan, dan bermusyawarah, lalu bertawakal setelah membulatkan tekad, yang menunjukkan penggabungan kelembutan dan keteguhan. Q.S. Thaha [20]: 44 memerintahkan berbicara kepada Fir aun dengan perkataan yang lemah lembut semoga ia ingat atau takut. Hadis menyebut bahwa tidaklah kelembutan ada pada sesuatu melainkan ia menghiasinya dan tidaklah kelembutan dicabut dari sesuatu melainkan ia memperburuknya. Hadis juga menyebut bahwa sombong adalah menolak kebenaran, yang menunjukkan bahwa keteguhan dalam kebenaran merupakan keharusan. Q.S. al-Ahzab [33]: 39 memuji orang yang tidak takut kepada siapa pun selain Allah. Karena itu penggabungan keduanya menghasilkan keteguhan yang efektif dalam menyampaikan kebenaran.'},
{level:'HOTS',indicator:'Menentukan cara menumbuhkan sifat pemurah pada diri sendiri',text:'Cara yang paling tepat untuk menumbuhkan sifat pemurah pada diri sendiri adalah ...',options:['menunggu hingga memiliki harta yang banyak baru mulai memberi','memulai dari jumlah kecil secara teratur dan tanpa diumumkan','tidak memberi sama sekali karena memberi dapat mengurangi harta','memaksa diri memberi dalam jumlah besar sekali saja agar terbiasa'],answer:1,explanation:'Hadis menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, sehingga memulai dengan jumlah kecil secara teratur merupakan cara yang tepat. Q.S. Ali Imran [3]: 92 menyebut bahwa kamu tidak akan memperoleh kebajikan yang sempurna sebelum menafkahkan sebagian harta yang kamu cintai. Hadis juga menyebut bahwa sebaik-baik sedekah adalah yang diberikan ketika masih sehat dan kikir serta mengharapkan kekayaan. Hadis menyebut bahwa tujuh golongan dinaungi Allah di antaranya orang yang bersedekah lalu menyembunyikannya sehingga tangan kirinya tidak mengetahui apa yang diinfakkan tangan kanannya. Q.S. an-Nahl [16]: 18 menyebut bahwa apabila menghitung nikmat Allah niscaya tidak mampu menghitungnya. Hadis menyebut bahwa agama seseorang mengikuti agama sahabat karibnya, sehingga bergaul dengan orang dermawan memengaruhi karakter. Hadis juga menyebut bahwa harta tidak berkurang karena sedekah. Q.S. Saba [34]: 39 menyebut bahwa Allah memberi ganti kepada orang yang menafkahkan hartanya.'},
{level:'HOTS',indicator:'Menentukan pengaruh penghayatan asmaul husna terhadap akhlak sehari-hari',text:'Dua orang pelajar memiliki tingkat ibadah yang sama tetapi salah satunya mempelajari makna asmaul husna dengan sungguh-sungguh sedangkan yang lain tidak. Analisis yang paling tepat terhadap perbedaan akhlak keduanya adalah ...',options:['pengenalan makna asmaul husna mengubah pengetahuan menjadi perilaku','pelajar yang tidak mempelajari asmaul husna tidak mungkin berakhlak baik','akhlak keduanya pasti sama karena tingkat ibadah mereka sama','mempelajari asmaul husna tidak berpengaruh pada akhlak karena akhlak dibentuk oleh kebiasaan'],answer:0,explanation:'Q.S. Fathir [35]: 28 menyebut bahwa yang benar-benar takut kepada Allah di antara hamba-hamba-Nya hanyalah para ulama, yang menunjukkan bahwa kedalaman pengenalan kepada Allah menghasilkan kedalaman ketakwaan dan perbaikan akhlak. Hadis menyebut bahwa Allah memiliki sembilan puluh sembilan nama dan barangsiapa menghafalnya akan masuk surga, dan para ulama menjelaskan bahwa menghafal mencakup memahami makna serta beramal sesuai tuntutannya. Hadis juga menyebut bahwa Allah Maha Pemurah dan menyukai orang yang pemurah, serta bahwa seorang mukmin adalah orang yang manusia lain merasa aman dari gangguannya. Q.S. ar-Rad [28]: 28 menegaskan bahwa hati menjadi tenteram dengan mengingat Allah. Hadis juga menyebut bahwa amal yang paling dicintai Allah adalah yang berkelanjutan walaupun sedikit, yang menunjukkan bahwa kebiasaan tetap penting, tetapi kebiasaan yang disertai penghayatan menghasilkan akhlak yang lebih kokoh dan lebih tahan terhadap ujian karena didasari pengenalan kepada Allah.'}
]});
